import React, { useState } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';
import { LogIn, User, Lock, Sparkles } from 'lucide-react';

const Login = () => {
    const [username, setUsername] = useState('');
    const [password, setPassword] = useState('');
    const [loading, setLoading] = useState(false);
    const { login } = useAuth();
    const navigate = useNavigate();

    const handleSubmit = async (e) => {
        e.preventDefault();
        setLoading(true);
        const success = await login(username, password);
        setLoading(false);
        if (success) {
            navigate('/dashboard');
        }
    };

    return (
        <div className="min-h-screen flex items-center justify-center bg-dark-primary p-4">
            <div className="bg-dark-card rounded-2xl shadow-2xl border border-dark-border p-8 max-w-md w-full">
                <div className="text-center mb-8">
                    <div className="flex justify-center mb-4">
                        <div className="w-16 h-16 rounded-full bg-gradient-main flex items-center justify-center glow-effect">
                            <Sparkles size={32} className="text-white" />
                        </div>
                    </div>
                    <h1 className="text-3xl font-bold gradient-text">RoadMap Tracker</h1>
                    <p className="text-light-secondary mt-2">Sign in to track your progress</p>
                </div>
                
                <form onSubmit={handleSubmit}>
                    <div className="mb-4">
                        <label className="block text-light-secondary text-sm font-medium mb-2">Username</label>
                        <div className="relative">
                            <User className="absolute left-3 top-3 text-light-muted" size={20} />
                            <input
                                type="text"
                                value={username}
                                onChange={(e) => setUsername(e.target.value)}
                                className="input-dark pl-10"
                                placeholder="Enter username"
                                required
                            />
                        </div>
                    </div>
                    
                    <div className="mb-6">
                        <label className="block text-light-secondary text-sm font-medium mb-2">Password</label>
                        <div className="relative">
                            <Lock className="absolute left-3 top-3 text-light-muted" size={20} />
                            <input
                                type="password"
                                value={password}
                                onChange={(e) => setPassword(e.target.value)}
                                className="input-dark pl-10"
                                placeholder="Enter password"
                                required
                            />
                        </div>
                    </div>
                    
                    <button
                        type="submit"
                        disabled={loading}
                        className="btn-primary w-full flex items-center justify-center gap-2 text-base"
                    >
                        <LogIn size={20} />
                        {loading ? 'Logging in...' : 'Login'}
                    </button>
                </form>
                
                <p className="text-center text-light-secondary mt-4 text-sm">
                    Don't have an account? <Link to="/register" className="text-accent-blue hover:text-accent-purple transition">Register</Link>
                </p>
            </div>
        </div>
    );
};

export default Login;
